Problem statement:
Read two integers on a single line separated by whitespace and print their sum followed by a newline.

Each integer fits in a signed 32-bit int (-2147483648 .. 2147483647). The sum may not.

Sample input:
7 5

Sample output:
12

Student file add_robust.c:
  1 | /*
  2 |  * add_robust.c - reads two integers and prints their sum.
  3 |  *
  4 |  * Each input fits in a 32-bit int, but their sum may not (2147483647 + 1),
  5 |  * so the operands are read and added as long long.
  6 |  */
  7 | #include <stdio.h>
  8 | #include <stdlib.h>
  9 | 
 10 | /* Reads the two operands; returns 1 on success and 0 on malformed input. */
 11 | static int read_operands(long long *lhs, long long *rhs)
 12 | {
 13 |     return scanf("%lld %lld", lhs, rhs) == 2;
 14 | }
 15 | 
 16 | /* Returns lhs + rhs; 64-bit arithmetic cannot overflow for 32-bit inputs. */
 17 | static long long add(long long lhs, long long rhs)
 18 | {
 19 |     return lhs + rhs;
 20 | }
 21 | 
 22 | int main(void)
 23 | {
 24 |     long long first_value;
 25 |     long long second_value;
 26 | 
 27 |     if (!read_operands(&first_value, &second_value)) {
 28 |         fprintf(stderr, "error: expected two integers on one line\n");
 29 |         return EXIT_FAILURE;
 30 |     }
 31 |     printf("%lld\n", add(first_value, second_value));
 32 |     return EXIT_SUCCESS;
 33 | }
